NativeSignal grp0_load_bitmap_file(VM& vm, Thread& thread) {
    const uint32_t file_address = thread.stack.pop();
    const uint32_t prefix_address = thread.stack.pop();
    const uint32_t type = thread.stack.pop();
    if (type >= 0x4000U) {
        throw std::runtime_error(
            "Grp0:0xC0 bitmap type is outside 0..0x3fff");
    }
    const std::string file =
        file_address == 0
            ? std::string()
            : vm.memory().read_cstring(file_address, thread.base);
    const std::string prefix =
        prefix_address == 0
            ? std::string()
            : vm.memory().read_cstring(prefix_address, thread.base);
    (void)vm.load_bitmap_file(type, prefix, file);
    return NativeSignal::Continue;
}
